css:
.hero{position:relative}
.hero img{width:100%;height:520px;object-fit:cover;object-position:70% center}
.hero__card{position:absolute;left:4%;top:50%;translate:0 -50%;
  width:41%;max-width:330px;background:#fff;padding:34px 30px;
  box-shadow:0 2px 20px rgba(0,0,0,.06)}
/* スクリム（linear-gradient や rgba黒のオーバーレイ）は敷かない */
@media(max-width:768px){.hero__card{position:static;width:auto;max-width:none;translate:0}}
